LANDING_HTML = '<!doctype html>\n<html lang="en">\n<head>\n  <meta charset="utf-8">\n  <meta name="viewport" content="width=device-width, initial-scale=1">\n  <meta name="description" content="Plan conference programs from proposal intake through the published schedule.">\n  <title>SessionBuddy · Conference program management</title>\n  <link rel="stylesheet" href="/landing/assets/landing.css?v=2">\n  <link rel="stylesheet" href="/app-shell/assets/app-shell.css?v=3">\n  <script src="/app-shell/assets/api-client.js?v=1" defer></script>\n  <script src="/app-shell/assets/app-shell.js?v=5" defer></script>\n</head>\n<body>\n  <a class="skip-link" href="#main">Skip to main content</a>\n  <header class="site-header">\n    <div class="page-shell nav-row">\n      <a class="brand" href="/" aria-label="SessionBuddy home">\n        <span class="brand-mark" aria-hidden="true">SB</span>\n        <span>SessionBuddy</span>\n      </a>\n      <nav class="primary-nav" aria-label="Primary navigation">\n        <a href="/speaker">Speaker portal</a>\n        <a href="/engine-room">Platform status</a>\n        <span data-landing-account><a class="nav-action" href="/sign-in?redirect=%2Fadmin">Sign in</a></span>\n      </nav>\n    </div>\n  </header>\n\n  <main id="main" tabindex="-1">\n    <section class="hero" aria-labelledby="hero-title">\n      <div class="page-shell hero-grid">\n        <div class="hero-copy">\n          <p class="eyebrow">Conference program management</p>\n          <h1 id="hero-title">Plan your conference program in one place.</h1>\n          <p class="hero-lede">Collect proposals, review sessions, prepare speakers, and publish the schedule.</p>\n          <div class="hero-actions">\n            <a class="button button-primary" data-auth-entry href="/sign-in?redirect=%2Fadmin">Sign in</a>\n            <a class="button button-secondary" href="/speaker">Speaker portal</a>\n          </div>\n          <ul class="proof-list" aria-label="Product assurances">\n            <li>Passwordless access</li>\n            <li>Private file delivery</li>\n            <li>Event-scoped permissions</li>\n          </ul>\n        </div>\n\n        <aside class="workflow-card" aria-labelledby="workflow-title">\n          <div class="workflow-heading">\n            <div>\n              <p class="panel-kicker">Program flow</p>\n              <h2 id="workflow-title">From proposal to schedule</h2>\n            </div>\n            <span class="ready-badge"><span aria-hidden="true"></span> Ready</span>\n          </div>\n          <ol class="workflow-list">\n            <li>\n              <span class="step-number">01</span>\n              <div><strong>Publish the CFP</strong><span>Flexible questions and drafts</span></div>\n              <span class="step-state">Open</span>\n            </li>\n            <li>\n              <span class="step-number">02</span>\n              <div><strong>Review fairly</strong><span>Blind scoring and conflicts</span></div>\n              <span class="step-state">Structured</span>\n            </li>\n            <li>\n              <span class="step-number">03</span>\n              <div><strong>Ready the speakers</strong><span>Tasks, files, and reminders</span></div>\n              <span class="step-state">On track</span>\n            </li>\n            <li>\n              <span class="step-number">04</span>\n              <div><strong>Publish the schedule</strong><span>Conflict-aware and calendar-ready</span></div>\n              <span class="step-state">Public</span>\n            </li>\n          </ol>\n        </aside>\n      </div>\n    </section>\n\n    <section class="role-section" aria-labelledby="roles-title">\n      <div class="page-shell">\n        <div class="section-heading">\n          <p class="eyebrow dark">One shared system</p>\n          <h2 id="roles-title">A clear view for every role.</h2>\n          <p>Each person sees the work and information relevant to them.</p>\n        </div>\n        <div class="role-grid">\n          <article class="role-card organizer-card">\n            <span class="role-label">For organizers</span>\n            <h3>Plan the program.</h3>\n            <p>Create events, publish forms, manage access, and release the agenda.</p>\n            <a href="/admin">Events <span aria-hidden="true">→</span></a>\n          </article>\n          <article class="role-card reviewer-card">\n            <span class="role-label">For reviewers</span>\n            <h3>Review consistently.</h3>\n            <p>Score assigned proposals with clear criteria and conflict controls.</p>\n            <a href="/reviews">Reviews <span aria-hidden="true">→</span></a>\n          </article>\n          <article class="role-card speaker-card">\n            <span class="role-label">For speakers</span>\n            <h3>Prepare for the event.</h3>\n            <p>Track sessions, complete tasks, and upload event materials.</p>\n            <a href="/speaker">Speaker portal <span aria-hidden="true">→</span></a>\n          </article>\n        </div>\n      </div>\n    </section>\n\n    <section class="platform-section" aria-labelledby="platform-title">\n      <div class="page-shell platform-grid">\n        <div>\n          <p class="eyebrow">Cloudflare-native</p>\n          <h2 id="platform-title">Built on Cloudflare.</h2>\n          <p>Fast delivery, relational data, private files, background work, and scheduled reminders.</p>\n          <a class="text-link" href="/engine-room">Platform status <span aria-hidden="true">→</span></a>\n        </div>\n        <ul class="stack-list" aria-label="Cloudflare services used by SessionBuddy">\n          <li><strong>Workers</strong><span>Python application</span></li>\n          <li><strong>D1</strong><span>Program data</span></li>\n          <li><strong>R2</strong><span>Private assets</span></li>\n          <li><strong>Queues</strong><span>Reliable delivery</span></li>\n          <li><strong>Workflows</strong><span>Timed reminders</span></li>\n        </ul>\n      </div>\n    </section>\n\n    <section class="closing-section" aria-labelledby="closing-title">\n      <div class="page-shell closing-card">\n        <div>\n          <p class="eyebrow dark">SessionBuddy</p>\n          <h2 id="closing-title">Ready to build your program?</h2>\n        </div>\n        <a class="button button-primary dark-button" data-auth-entry href="/sign-in?redirect=%2Fadmin">Sign in</a>\n      </div>\n    </section>\n  </main>\n\n  <footer>\n    <div class="page-shell footer-row">\n      <span>SessionBuddy</span>\n      <span>Conference program management.</span>\n    </div>\n  </footer>\n</body>\n</html>\n'

